/* eslint-disable @typescript-eslint/no-explicit-any */
import { IUserPreferenceConfig } from '@game-studio/settings';
import { ChatSizeOption } from '../../types';

export interface ISettingsConfigs {
    navigation: {
        howToPlay: ISettingsAction;
        demoMode?: ISettingsAction;
    },
    userPrefs: {
        sound: IUserPreferenceConfigEx;
        music: IUserPreferenceConfigEx;
        chatSize: IUserPreferenceConfigEx;
        chatColour: IUserPreferenceConfigEx;
        notifications: IUserPreferenceConfigEx;
        oneHandedPlay: IUserPreferenceConfigEx;
        colourBlindMode: IUserPreferenceConfigEx;
    },
    subMenus: {
        recentWinners: ISettingsInfoOptions;
        gameRules: ISettingsInfoOptions;
        chatRules: ISettingsInfoOptions;
    }
    labels: {
        sessionNumber: ISettingsInfoOptions;
        gameNumber: ISettingsInfoOptions;
    },
    version: ISettingsInfoOptions
}

export interface ISettingsInfoOptions {
    label: string;
    value: string;
}

export interface ISettingsAction {
    label: string;
    onClick: (...args: any[]) => void;
}

export interface IUserPreferenceConfigEx extends IUserPreferenceConfig {
    value?: string
    onClick: ((val: boolean) => void) | ((val: number) => void) | ((val: string) => void) | ((val: ChatSizeOption) => void);
}

export interface IAdditionalSettingsItem {
    sectionId: 1 | 2 | 3;
    item: SettingsItem;
    index: number;
}

export type SettingsItem = ISettingsLabel | ISettingsExternalLink | ISettingsComponentLink | ISettingsColourSwatch | ISettingsCheckBox | IMultiCheckBox;

export interface ISettingsLabel {
    type: 'label-field';
    label: { text: string; };
    field: { text: string };
}

export interface ISettingsExternalLink {
    type: 'external-link';
    name: string;
    onClick: (...args: any[]) => void;
}

export interface ISettingsComponentLink {
    type: 'component-link';
    name: string;
    component?: any;
    path: 'how-to-play' | 'recent-winners' | 'game-rules' | 'chat-rules';
    onClick?: (...args: any[]) => void;
}

export interface ISettingsColourSwatch {
    type: 'chat-colour-swatch';
    name: string;
    onClick: (val: number) => void;
    toggle: string;
}

export interface ISettingsCheckBox {
    type: 'checkbox';
    name: string;
    onClick: (val: boolean) => void;
    toggle: string;
    default?: boolean;
}

export interface IMultiCheckBox {
    type: 'multi-checkbox';
    name: string;
    onClick: (val: number) => void;
    toggle: string;
    options: Array<{ label: string; value: number }>;
}

